fn main() {
    let text = "من جد وجد ومن زرع حصد ومن سار على الدرب وصل"
    let words = text.words()
    print("عدد الكلمات:", words.length)
    match words.max_by(|w| w.length) {
        Some(w) => print("أطول كلمة:", w)
        None => print("لا كلمات")
    }
    print("بالعكس:", words.reverse().join(" "))
    let counts = words.group_by(|w| w)
    for word in counts.keys().sorted() {
        let n = counts[word].length
        if n > 1 {
            print("«{word}» تكررت {n} مرات")
        }
    }
}

