enum Shape {
    Circle(Float)
    Rect(Float, Float)
}

fn area(s: Shape) -> Float {
    return match s {
        Shape.Circle(r) => 3.14159 * r * r
        Shape.Rect(w, h) => w * h
    }
}

fn parse_age(text: String) -> Result<Int, String> {
    return match text.parse_int() {
        Some(n) => Ok(n)
        None => Err("'{text}' is not a number")
    }
}

fn main() {
    print(area(Shape.Circle(1.0)), area(Shape.Rect(2.0, 3.0)))
    print(parse_age("42"), parse_age("abc"))
}

use std.json

type Book = { title: String, year: Int, tags: List<String> }

fn main() {
    let text = r#"[{"title": "Kalila wa Dimna", "year": 750, "tags": ["fables"]},"#
        + r#"{"title": "The Muqaddimah", "year": 1377, "tags": ["history", "science"]}]"#
    match json.parse<List<Book>>(text) {
        Ok(books) => {
            for b in books.sort_by(|b| b.year) {
                print("{b.year}: {b.title} ({b.tags.join(", ")})")
            }
            print(json.stringify(books.map(|b| b.title)))
        }
        Err(e) => print("not valid:", e)
    }
    // A value of the wrong type is an error you handle, not a crash.
    print(json.parse<List<Book>>(r#"[{"title": 5}]"#).is_err())
}

use std.time

fn main() {
    let start = time.make(2026, 1, 1)
    let exam = time.make(2026, 6, 15)
    print("days until the exam:", time.days_between(start, exam))
    let next = time.add_months(exam, 3)
    print("three months later:", time.format_as(next, "YYYY-MM-DD"))
    for week in 1..=3 {
        print("week {week}:", time.format_as(time.add_days(start, 7 * week), "DD/MM"))
    }
}

fn is_prime(n: Int) -> Bool {
    if n < 2 {
        return false
    }
    var d = 2
    while d * d <= n {
        if n % d == 0 {
            return false
        }
        d += 1
    }
    return true
}

fn main() {
    var numbers = []
    for n in 1..50000 {
        numbers.push(n)
    }
    // par_filter checks the numbers on every processor core
    // (in the browser, one after another), with the same result.
    let primes = numbers.par_filter(is_prime)
    print("primes below 50000:", primes.length)
    print("the last five:", primes.skip(primes.length - 5))
}

