use std.ai

enum Priority {
    Low
    Normal
    Urgent
}

type Ticket = { category: String, priority: Priority, summary: String }

async fn main() {
    // "mock" answers offline with a value of the type you ask for.
    // With a real model only the name changes: "gpt", "claude" or "local".
    let message = "The app crashes every time I open it!"
    match await ai.infer<Ticket>(
        model: "mock",
        instructions: "Classify the support message",
        input: message
    ) {
        Ok(t) => {
            let label = match t.priority {
                Priority.Urgent => "now"
                Priority.Normal => "today"
                Priority.Low => "this week"
            }
            print("category:", t.category, "| answer:", label)
        }
        Err(e) => print("the model failed:", e.kind())
    }
}
